import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db,send,asset,reviewed,task}=await import('./reply-runtime-20261015.mjs');const source=JSON.parse(await fs.readFile('artifacts/local-reassurance-20261019/review.json'));const dir='artifacts/replies-715pm-20261019';await fs.mkdir(dir,{recursive:true});const plans=[['Wang Yeung Eric Hui',"Here's our Richmond Hill card. We provide a firm quote upfront for the agreed move, based on the items, pickup and destination, access and any packing needed. Is this for a particular move or information to keep for future clients? - John",true],['ANDREA BROWN',"Here you go, Andrea—our Vaughan card to save and share when a client needs moving help. You can call or text me here. - John",true],['Tasha Slater',"Haha, fair enough, Tasha! Let's find a time for next week. What two days and times would suit you, and would you prefer your Kingsville or Essex office? I'll check my calendar and confirm one so we can put it in our schedules. Looking forward to talking about the staging moves. - John",false]];const results=[];
for(const[name,body,card]of plans){const r=source.rows.find(r=>r.contact.name===name);const c=r.contact,last=r.thread.at(-1);const phone='+1'+c.phone.replace(/\D/g,'').slice(-10);const sms=await db('sms_messages',{or:`(from_number.eq.${phone},to_number.eq.${phone})`,created_at:'gte.'+last.created_at,limit:'50'});if(sms.some(t=>t.direction==='outbound'))throw Error('New sales reply '+name);try{const result=await send({id:c.id,name:c.name,phone:c.phone,city:c.city,latest:last.id,from:last.metadata.to,body,media_urls:card?[await asset(c.city)]:[],followup_key:'20261019-715pm',note:'Requested contextual response. Meeting proposed only; no appointment or live move invented.'});results.push({name,state:result.state});if(name==='Tasha Slater'&&result.state==='accepted')await task(c,'tasha-meet-nextweek-20261019','Tasha Slater: confirm staging meet-and-greet next week','Tasha wants to schedule next week (October 26–November 1). Asked for two day/time options and Kingsville or Essex office preference. John must check calendar and confirm exact date, time and address before booking. Preserve +12268870667 sender. No meeting booked yet.',{due_at:'2026-10-20T14:00:00Z'});}catch(e){results.push({name,state:'held',reason:e.message});}await fs.writeFile(dir+'/results.json',JSON.stringify(results,null,2));}
for(const name of ['LUBA HENDERSON','Lydia De Santis','MASOUD ZANGENEH']){const r=source.rows.find(r=>r.contact.name===name);const last=r.thread.at(-1);const[now]=await db('market_touches',{contact_id:'eq.'+r.contact.id,order:'created_at.desc',limit:'1'});if(now.id!==last.id)continue;const lastOut=r.thread.findLastIndex(t=>t.direction==='outbound');for(const t of r.thread.slice(lastOut+1).filter(t=>t.direction==='inbound'))await reviewed(t.id,name==='LUBA HENDERSON'?'Acknowledged coverage; recent clients in Richmond Hill/Mississauga, no current move disclosed. No extra nudge.':'Acknowledgement/reaction only; no extra message.');await db('market_contacts',{id:'eq.'+r.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'human_managed_relationship',next_follow_up:null});results.push({name,state:'reviewed_no_reply'});}await fs.writeFile(dir+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));
